WITH parsed AS (SELECT id, service, host, log_ts, level, payload_json, context, context['trace'] AS trace, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, COALESCE(context['trace'], 'direct') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT *, NTILE(4) OVER (PARTITION BY level ORDER BY retry_count, id) AS retry_count_bucket, ROW_NUMBER() OVER (PARTITION BY service, level ORDER BY retry_count DESC, id) AS event_seq FROM parsed WHERE host IN ('h3', 'h2')
